import json
import math
import re
from dataclasses import dataclass
from datetime import date, datetime
from pathlib import Path
from typing import Any

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
import shap
from matplotlib.figure import Figure

from backend.src.xai.xai_result import (
    AccumulatedLocalEffectsResult,
    GlobalShapExplanation,
    LocalShapExplanation,
    PartialDependenceResult,
)


@dataclass(frozen=True, slots=True)
class XAIExportPaths:
    """Store paths generated by the XAI exporter."""

    local_shap_csv: Path
    global_shap_importance_csv: Path
    global_shap_feature_values_csv: Path
    global_shap_contributions_csv: Path
    partial_dependence_csv: Path
    accumulated_local_effects_csv: Path
    result_json: Path
    plot_files: dict[str, Path]


def export_xai_results(
    local_explanation: LocalShapExplanation,
    global_explanation: GlobalShapExplanation,
    partial_dependence_results: dict[
        str,
        PartialDependenceResult,
    ],
    accumulated_local_effects_results: dict[
        str,
        AccumulatedLocalEffectsResult,
    ],
    output_directory: Path,
    metadata: dict[str, object] | None = None,
    max_display_features: int = 15,
) -> XAIExportPaths:
    """Export XAI tables, plots and a JSON manifest."""
    if max_display_features <= 0:
        raise ValueError(
            "max_display_features must be greater than zero.",
        )

    _validate_feature_effect_results(
        partial_dependence_results,
        accumulated_local_effects_results,
    )

    output_directory.mkdir(
        parents=True,
        exist_ok=True,
    )
    plot_directory = output_directory / "plots"
    plot_directory.mkdir(
        parents=True,
        exist_ok=True,
    )

    local_shap_path = output_directory / "local_shap.csv"
    global_importance_path = output_directory / "global_shap_importance.csv"
    global_feature_values_path = output_directory / "global_shap_feature_values.csv"
    global_contributions_path = output_directory / "global_shap_contributions.csv"
    partial_dependence_path = output_directory / "partial_dependence.csv"
    accumulated_local_effects_path = output_directory / "accumulated_local_effects.csv"
    result_path = output_directory / "xai_result.json"

    local_table = _build_local_shap_table(
        local_explanation,
    )
    global_importance_table = _build_global_importance_table(
        global_explanation,
    )
    global_feature_values_table = _prepare_indexed_frame(
        global_explanation.feature_values,
    )
    global_contributions_table = _prepare_indexed_frame(
        global_explanation.feature_contributions,
    )
    partial_dependence_table = _build_partial_dependence_table(
        partial_dependence_results,
    )
    accumulated_local_effects_table = _build_accumulated_local_effects_table(
        accumulated_local_effects_results,
    )

    local_table.to_csv(
        local_shap_path,
        index=False,
    )
    global_importance_table.to_csv(
        global_importance_path,
        index=False,
    )
    global_feature_values_table.to_csv(
        global_feature_values_path,
        index=False,
    )
    global_contributions_table.to_csv(
        global_contributions_path,
        index=False,
    )
    partial_dependence_table.to_csv(
        partial_dependence_path,
        index=False,
    )
    accumulated_local_effects_table.to_csv(
        accumulated_local_effects_path,
        index=False,
    )

    plot_files = _create_plots(
        local_explanation=local_explanation,
        global_explanation=global_explanation,
        partial_dependence_results=(partial_dependence_results),
        accumulated_local_effects_results=(accumulated_local_effects_results),
        plot_directory=plot_directory,
        max_display_features=max_display_features,
    )

    payload = _build_json_payload(
        local_explanation=local_explanation,
        global_explanation=global_explanation,
        partial_dependence_results=(partial_dependence_results),
        accumulated_local_effects_results=(accumulated_local_effects_results),
        metadata=metadata or {},
        plot_files=plot_files,
        output_directory=output_directory,
    )

    result_path.write_text(
        json.dumps(
            payload,
            ensure_ascii=False,
            indent=2,
            allow_nan=False,
        )
        + "\n",
        encoding="utf-8",
    )

    return XAIExportPaths(
        local_shap_csv=local_shap_path,
        global_shap_importance_csv=(global_importance_path),
        global_shap_feature_values_csv=(global_feature_values_path),
        global_shap_contributions_csv=(global_contributions_path),
        partial_dependence_csv=(partial_dependence_path),
        accumulated_local_effects_csv=(accumulated_local_effects_path),
        result_json=result_path,
        plot_files=plot_files,
    )


def _validate_feature_effect_results(
    partial_dependence_results: dict[
        str,
        PartialDependenceResult,
    ],
    accumulated_local_effects_results: dict[
        str,
        AccumulatedLocalEffectsResult,
    ],
) -> None:
    partial_features = set(
        partial_dependence_results,
    )
    ale_features = set(
        accumulated_local_effects_results,
    )

    if not partial_features:
        raise ValueError(
            "At least one feature effect result is required.",
        )

    if partial_features != ale_features:
        raise ValueError(
            "PDP and ALE results must contain the same feature names.",
        )

    for feature_name, result in partial_dependence_results.items():
        if result.feature_name != feature_name:
            raise ValueError(
                "PDP result key must match its feature_name.",
            )

    for feature_name, result in accumulated_local_effects_results.items():
        if result.feature_name != feature_name:
            raise ValueError(
                "ALE result key must match its feature_name.",
            )


def _build_local_shap_table(
    explanation: LocalShapExplanation,
) -> pd.DataFrame:
    return pd.DataFrame(
        {
            "feature": (explanation.feature_values.index.astype(str)),
            "feature_value": (
                explanation.feature_values.to_numpy(
                    dtype=float,
                )
            ),
            "shap_value": (
                explanation.feature_contributions.to_numpy(
                    dtype=float,
                )
            ),
        }
    )


def _build_global_importance_table(
    explanation: GlobalShapExplanation,
) -> pd.DataFrame:
    importance = explanation.mean_absolute_contributions

    return pd.DataFrame(
        {
            "feature": (importance.index.astype(str)),
            "mean_absolute_shap_value": (
                importance.to_numpy(
                    dtype=float,
                )
            ),
        }
    )


def _prepare_indexed_frame(
    data: pd.DataFrame,
) -> pd.DataFrame:
    prepared = data.copy(
        deep=True,
    )
    prepared.index.name = "observation_index"

    return prepared.reset_index()


def _build_partial_dependence_table(
    results: dict[
        str,
        PartialDependenceResult,
    ],
) -> pd.DataFrame:
    rows: list[dict[str, object]] = []

    for feature_name in sorted(results):
        result = results[feature_name]

        rows.extend(
            {
                "feature": feature_name,
                "feature_value": float(result.feature_values.iloc[row_index]),
                "average_prediction": float(result.average_predictions.iloc[row_index]),
            }
            for row_index in range(len(result.feature_values))
        )

    return pd.DataFrame(rows)


def _build_accumulated_local_effects_table(
    results: dict[
        str,
        AccumulatedLocalEffectsResult,
    ],
) -> pd.DataFrame:
    rows: list[dict[str, object]] = []

    for feature_name in sorted(results):
        result = results[feature_name]

        rows.extend(
            {
                "feature": feature_name,
                "lower_edge": float(result.bin_edges.iloc[row_index]),
                "upper_edge": float(result.bin_edges.iloc[row_index + 1]),
                "bin_center": float(result.bin_centers.iloc[row_index]),
                "local_effect": float(result.local_effects.iloc[row_index]),
                "accumulated_effect": float(result.accumulated_effects.iloc[row_index]),
                "sample_count": int(result.sample_counts.iloc[row_index]),
            }
            for row_index in range(len(result.bin_centers))
        )

    return pd.DataFrame(rows)


def _create_plots(
    local_explanation: LocalShapExplanation,
    global_explanation: GlobalShapExplanation,
    partial_dependence_results: dict[
        str,
        PartialDependenceResult,
    ],
    accumulated_local_effects_results: dict[
        str,
        AccumulatedLocalEffectsResult,
    ],
    plot_directory: Path,
    max_display_features: int,
) -> dict[str, Path]:
    plot_files: dict[str, Path] = {}

    local_waterfall_path = plot_directory / "local_shap_waterfall.png"
    global_bar_path = plot_directory / "global_shap_bar.png"
    global_beeswarm_path = plot_directory / "global_shap_beeswarm.png"

    _plot_local_shap(
        explanation=local_explanation,
        output_path=local_waterfall_path,
        max_display_features=max_display_features,
    )
    _plot_global_shap_bar(
        explanation=global_explanation,
        output_path=global_bar_path,
        max_display_features=max_display_features,
    )
    _plot_global_shap_beeswarm(
        explanation=global_explanation,
        output_path=global_beeswarm_path,
        max_display_features=max_display_features,
    )

    plot_files["local_shap_waterfall"] = local_waterfall_path
    plot_files["global_shap_bar"] = global_bar_path
    plot_files["global_shap_beeswarm"] = global_beeswarm_path

    for feature_name in sorted(partial_dependence_results):
        safe_feature_name = _safe_file_name(
            feature_name,
        )

        pdp_path = plot_directory / f"pdp_{safe_feature_name}.png"
        ale_path = plot_directory / f"ale_{safe_feature_name}.png"

        _plot_partial_dependence(
            result=(partial_dependence_results[feature_name]),
            output_path=pdp_path,
        )
        _plot_accumulated_local_effects(
            result=(accumulated_local_effects_results[feature_name]),
            output_path=ale_path,
        )

        plot_files[f"pdp:{feature_name}"] = pdp_path
        plot_files[f"ale:{feature_name}"] = ale_path

    return plot_files


def _plot_local_shap(
    explanation: LocalShapExplanation,
    output_path: Path,
    max_display_features: int,
) -> None:
    shap_explanation = shap.Explanation(
        values=(
            explanation.feature_contributions.to_numpy(
                dtype=float,
            )
        ),
        base_values=explanation.base_value,
        data=(
            explanation.feature_values.to_numpy(
                dtype=float,
            )
        ),
        feature_names=(explanation.feature_values.index.tolist()),
    )

    shap.plots.waterfall(
        shap_explanation,
        max_display=max_display_features,
        show=False,
    )
    _save_current_figure(
        output_path,
    )


def _plot_global_shap_bar(
    explanation: GlobalShapExplanation,
    output_path: Path,
    max_display_features: int,
) -> None:
    shap_explanation = _build_global_shap_explanation(
        explanation,
    )

    shap.plots.bar(
        shap_explanation,
        max_display=max_display_features,
        show=False,
    )
    _save_current_figure(
        output_path,
    )


def _plot_global_shap_beeswarm(
    explanation: GlobalShapExplanation,
    output_path: Path,
    max_display_features: int,
) -> None:
    shap_explanation = _build_global_shap_explanation(
        explanation,
    )

    shap.plots.beeswarm(
        shap_explanation,
        max_display=max_display_features,
        show=False,
    )
    _save_current_figure(
        output_path,
    )


def _build_global_shap_explanation(
    explanation: GlobalShapExplanation,
) -> shap.Explanation:
    return shap.Explanation(
        values=(
            explanation.feature_contributions.to_numpy(
                dtype=float,
            )
        ),
        base_values=(
            explanation.base_values.to_numpy(
                dtype=float,
            )
        ),
        data=(
            explanation.feature_values.to_numpy(
                dtype=float,
            )
        ),
        feature_names=(explanation.feature_values.columns.tolist()),
    )


def _plot_partial_dependence(
    result: PartialDependenceResult,
    output_path: Path,
) -> None:
    figure, axis = plt.subplots(
        figsize=(
            8,
            5,
        )
    )
    axis.plot(
        result.feature_values,
        result.average_predictions,
        color="#2563EB",
        linewidth=2.0,
    )
    axis.axhline(
        0.0,
        color="#64748B",
        linewidth=1.0,
        linestyle="--",
    )
    axis.set_title(
        f"Partial dependence: {result.feature_name}",
    )
    axis.set_xlabel(
        result.feature_name,
    )
    axis.set_ylabel(
        "Average predicted next-session return",
    )
    axis.grid(
        alpha=0.25,
    )

    _save_figure(
        figure,
        output_path,
    )


def _plot_accumulated_local_effects(
    result: AccumulatedLocalEffectsResult,
    output_path: Path,
) -> None:
    figure, axis = plt.subplots(
        figsize=(
            8,
            5,
        )
    )
    axis.plot(
        result.bin_centers,
        result.accumulated_effects,
        color="#059669",
        marker="o",
        linewidth=2.0,
    )
    axis.axhline(
        0.0,
        color="#64748B",
        linewidth=1.0,
        linestyle="--",
    )
    axis.set_title(
        f"Accumulated local effects: {result.feature_name}",
    )
    axis.set_xlabel(
        result.feature_name,
    )
    axis.set_ylabel(
        "Centered effect on predicted return",
    )
    axis.grid(
        alpha=0.25,
    )

    _save_figure(
        figure,
        output_path,
    )


def _save_current_figure(
    output_path: Path,
) -> None:
    figure = plt.gcf()
    _save_figure(
        figure,
        output_path,
    )


def _save_figure(
    figure: Figure,
    output_path: Path,
) -> None:
    figure.savefig(
        output_path,
        dpi=200,
        bbox_inches="tight",
    )
    plt.close(
        figure,
    )


def _safe_file_name(
    value: str,
) -> str:
    safe_value = re.sub(
        r"[^A-Za-z0-9._-]+",
        "_",
        value,
    ).strip(
        "._",
    )

    if not safe_value:
        raise ValueError(
            "Feature name cannot be converted to a safe file name.",
        )

    return safe_value


def _build_json_payload(
    local_explanation: LocalShapExplanation,
    global_explanation: GlobalShapExplanation,
    partial_dependence_results: dict[
        str,
        PartialDependenceResult,
    ],
    accumulated_local_effects_results: dict[
        str,
        AccumulatedLocalEffectsResult,
    ],
    metadata: dict[str, object],
    plot_files: dict[str, Path],
    output_directory: Path,
) -> dict[str, object]:
    return {
        "schema_version": 1,
        "metadata": {
            key: _json_value(value) for key, value in sorted(metadata.items())
        },
        "methods": [
            "shap",
            "partial_dependence",
            "accumulated_local_effects",
        ],
        "local_shap": {
            "base_value": _finite_float(
                local_explanation.base_value,
            ),
            "prediction": _finite_float(
                local_explanation.prediction,
            ),
            "reconstructed_prediction": (
                _finite_float(local_explanation.reconstructed_prediction)
            ),
            "features": [
                {
                    "feature": str(feature_name),
                    "feature_value": _finite_float(
                        local_explanation.feature_values.loc[feature_name]
                    ),
                    "shap_value": _finite_float(
                        local_explanation.feature_contributions.loc[feature_name]
                    ),
                }
                for feature_name in (local_explanation.feature_values.index)
            ],
        },
        "global_shap": {
            "observations": len(
                global_explanation.feature_values,
            ),
            "mean_absolute_contributions": {
                str(feature_name): _finite_float(
                    contribution,
                )
                for feature_name, contribution in (
                    global_explanation.mean_absolute_contributions.items()
                )
            },
        },
        "partial_dependence": {
            feature_name: {
                "feature_values": [
                    _finite_float(value) for value in (result.feature_values)
                ],
                "average_predictions": [
                    _finite_float(value) for value in (result.average_predictions)
                ],
            }
            for feature_name, result in sorted(partial_dependence_results.items())
        },
        "accumulated_local_effects": {
            feature_name: {
                "bin_edges": [_finite_float(value) for value in result.bin_edges],
                "bin_centers": [_finite_float(value) for value in result.bin_centers],
                "accumulated_effects": [
                    _finite_float(value) for value in (result.accumulated_effects)
                ],
                "sample_counts": [int(value) for value in result.sample_counts],
            }
            for feature_name, result in sorted(
                accumulated_local_effects_results.items()
            )
        },
        "plots": {
            name: str(
                path.relative_to(
                    output_directory,
                )
            )
            for name, path in sorted(plot_files.items())
        },
    }


def _json_value(
    value: object,
) -> object:
    if isinstance(
        value,
        (
            pd.Timestamp,
            datetime,
            date,
        ),
    ):
        return value.isoformat()

    if isinstance(
        value,
        (
            np.integer,
            int,
        ),
    ):
        return int(value)

    if isinstance(
        value,
        (
            np.floating,
            float,
        ),
    ):
        return _finite_float(value)

    if value is None or isinstance(
        value,
        (
            str,
            bool,
        ),
    ):
        return value

    return str(value)


def _finite_float(
    value: Any,
) -> float:
    numeric_value = float(value)

    if not math.isfinite(numeric_value):
        raise ValueError(
            "XAI results must contain only finite values.",
        )

    return numeric_value
